import{_ as t,b as i,e as o,a8 as a}from"./chunks/framework.CD0vREyi.js";const h=JSON.parse('{"title":"SIMD optimizations","description":"","frontmatter":{"date":1787703538000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"guide/simd-optimizations.md","filePath":"guide/simd-optimizations.md","lastUpdated":1787703538000,"timestamp":1787703538000,"datetime":"2026-08-26T00:18:58.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),s={name:"guide/simd-optimizations.md"};function n(r,e,l,c,p,d){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="simd-optimizations" tabindex="-1">SIMD optimizations <a class="header-anchor" href="#simd-optimizations" aria-label="Permalink to &quot;SIMD optimizations&quot;">​</a></h1><p>In order to achieve the best possible performance on a given host platform, Graphics32 implements most low level bottlenecks using <a href="https://en.wikipedia.org/wiki/Single_instruction,_multiple_data" target="_blank" rel="noreferrer">SIMD</a> optimized assembly instructions. SIMD instructions enable the CPU to execute multiple similar calculations in parallel and is thus particularly well suited for graphics processing where the same operation is often performed on the R, G, B, and possibly A channels, of an image.</p><p>Since the level of SIMD support varies with different CPU models, Graphics32 provides different implementations for different SIMD support levels and <a href="./cpu-feature-detection/">automatically uses the best possible variant</a>.</p><div class="right custom-block"><div class="warning custom-block"><p class="custom-block-title">MMX is no longer supported</p><p>Support for the MMX SIMD instruction was deprecated in Graphics32 version 3 and has been removed from version 4.</p><p>Not all documentation has been updated to reflect this, so please ignore all references to MMX code.</p></div></div><p>The most basic SIMD support is based on the <a href="https://en.wikipedia.org/wiki/MMX_(instruction_set)" target="_blank" rel="noreferrer">MMX</a> instruction set. Since MMX was introduced in 1997 it is supported by all processors supported by Delphi and thus Graphics32. Newer processors all support the <a href="https://en.wikipedia.org/wiki/Streaming_SIMD_Extensions" target="_blank" rel="noreferrer">SSE</a> (introduced 1999) and <a href="https://en.wikipedia.org/wiki/SSE2" target="_blank" rel="noreferrer">SSE2</a> (introduced 2000) instruction sets and today MMX support is <em>only</em> included in Graphics32 for backward compatibility and as a reference.</p><h3 id="mmx-vs-sse" tabindex="-1">MMX vs SSE <a class="header-anchor" href="#mmx-vs-sse" aria-label="Permalink to &quot;MMX vs SSE&quot;">​</a></h3><p>The reason to favor SSE* optimizations over MMX optimizations is mainly due to MMX’s use of the x87 FPU’s floating point registers. As long as all processing is done solely in fixed point or integer registers, there is no problem, but if floating point calculations needs to be done after MMX has used the FPU registers, then an expensive reset of the FPU registers must first be performed or else a floating point exception will be thrown. This reset is performed within the <a href="https://www.felixcloutier.com/x86/emms" target="_blank" rel="noreferrer">EMMS</a> function (an intrinsic to the assembler mnemonic with the same name).</p><p>It should be noted that even though a call to EMMS uses only a handful of cycles, frequent calls can slow down simple processing such as alpha blending a lot.</p><h3 id="the-omit-mmx-compiler-conditional" tabindex="-1">The OMIT_MMX compiler conditional <a class="header-anchor" href="#the-omit-mmx-compiler-conditional" aria-label="Permalink to &quot;The OMIT_MMX compiler conditional&quot;">​</a></h3><p>The support for MMX optimizations can be controlled with the <code>OMIT_MMX</code> compiler conditional:</p><ul><li><p>When <code>OMIT_MMX</code> is defined, Graphics32&#39;s use of MMX optimizations will be entirely disabled. The EMMS function becomes an empty static function that does nothing and which, due to compiler inlining, has no cost.</p></li><li><p>When <code>OMIT_MMX</code> is <em>not</em> defined, the MMX optimizations will be included and by default the EMMS function will execute the <em>emms</em> assembler instruction. However if Graphics32’s CPU feature detection has selected a newer SIMD technology, such as SSE or SSE2, then the EMMS function just becomes an empty virtual function that does nothing and the cost of calling it is nothing more than a call and return.</p></li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>As all x86 64-bit processors feature the SSE2 instructions, <code>OMIT_MMX</code> is defined by default when targeting that platform. This not only results in better performance, but also in smaller executables.</p></div>',12)])])}const u=t(s,[["render",n]]);export{h as __pageData,u as default};
